solution.solution.cpp:
#include <mutex>

class Counter
{
public:
    void increment()
    {
        const std::lock_guard lock{ m_mutex };
        ++m_value;
    }

    int value() const
    {
        const std::lock_guard lock{ m_mutex };
        return m_value;
    }

private:
    mutable std::mutex m_mutex{};
    int m_value{ 0 };
};

unitTests:
#include <thread>
TEST("single-threaded use") { Counter c{}; c.increment(); c.increment(); CHECK_EQ(c.value(), 2); }
TEST("no increments are lost with 8 threads") {
    for (int round{ 0 }; round < 5; ++round)
    {
        Counter c{};
        {
            std::vector<std::jthread> threads;
            for (int t{ 0 }; t < 8; ++t) threads.emplace_back([&c] { for (int i{ 0 }; i < 20000; ++i) c.increment(); });
        }
        CHECK_EQ(c.value(), 160000);
    }
}

